using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using kok;
public static class WarehouseTests {
 static IEnumerable<string> CancelAfterFirst(string first,string second,CancellationTokenSource cancel){yield return first;cancel.Cancel();yield return second;}
 static bool Reject(Action action){try{action();return false;}catch(InvalidOperationException){return true;}catch(InvalidDataException){return true;}}
 public static void Run(string root,Action<bool,string> check){
  Directory.CreateDirectory(root);string source=Path.Combine(root,"original.md");File.WriteAllText(source,"# 中文测试\n\n模块化仓库支持全文检索。",new UTF8Encoding(false));
  string data=Path.Combine(root,"data");Directory.CreateDirectory(data);var entry=new Entry{id=Guid.NewGuid().ToString("N"),name="原始资料",kind="document",ext="MD",path=source,notes="迁移的想法"};var old=new Database{items=new List<Entry>{entry}};string original=Library.Json.Serialize(old);File.WriteAllText(Path.Combine(data,"library.json"),original,new UTF8Encoding(false));
  var lib=new Library(data);check(File.ReadAllText(Path.Combine(data,"library.json"))==original&&File.ReadAllText(Path.Combine(data,"library.json.pre-0.8.1"))==original,"SQLite migration preserves both the original JSON and an exact named backup");
  check(Encoding.ASCII.GetString(File.ReadAllBytes(lib.StoragePath),0,15)=="SQLite format 3"&&lib.Find(entry.id).notes=="迁移的想法","the canonical library is SQLite and facet data survives migration");
  lib.IndexItem(lib.Find(entry.id),Library.ReadText(source));check(lib.FullTextSearch("全文检索").Contains(entry.id)&&lib.FullTextSearch("全文").Contains(entry.id),"FTS5 covers Chinese body phrases and short queries use a local substring fallback");
  lib.Update(entry.id,new Dictionary<string,object>{{"favorite",true},{"notes","事务后的笔记"}});var op=lib.OperationList().Last(o=>o.title=="编辑资料");lib.OperationUndo(op.id);check(!lib.Find(entry.id).favorite&&lib.Find(entry.id).notes=="迁移的想法","ordinary file edits share atomic global history and undo");
  bool invalid=Reject(()=>lib.Update(entry.id,new Dictionary<string,object>{{"favorite",true},{"bookmarks",new[]{new ReadingBookmark{id="",name="bad"}}}}));check(invalid&&!lib.Find(entry.id).favorite,"invalid late fields do not partially change earlier fields");
  var space=new SpaceRecord{id=Guid.NewGuid().ToString("N"),name="空间",created=DateTime.UtcNow.ToString("o"),members=new List<string>{entry.id}};var proposal=lib.ProposeResource("space",space.id,Library.Json.Serialize(space));lib.OperationApply(proposal.id);space.view="canvas";var second=lib.ProposeResource("space",space.id,Library.Json.Serialize(space));lib.OperationApply(second.id);lib.OperationUndo(second.id);check(((WorkspaceState)new Library(data).WorkspaceSnapshot()).spaces.Single().view=="grid","space edits use canonical snapshots and undo survives restart");
  var clip=new ClipRecord{id=Guid.NewGuid().ToString("N"),title="摘录",text="模块化仓库",created=DateTime.UtcNow.ToString("o"),source=new SourceAnchor{itemId=entry.id,text="模块化仓库"}};var clipOp=lib.ProposeResource("clip",clip.id,Library.Json.Serialize(clip));lib.OperationApply(clipOp.id);lib.OperationUndo(clipOp.id);check(((WorkspaceState)lib.WorkspaceSnapshot()).clips.Count==0,"clip creation is reversible without changing source bytes");
  var query=new CollectionQuery{id=Guid.NewGuid().ToString("N"),name="自动查询",query="全文"};check(lib.QueryCollection(query).Contains(entry.id),"smart collections resolve their saved criteria against indexed content");
  lib.SetAppMode("smart",true);var state=new AgentTaskState{id=Guid.NewGuid().ToString("N"),options=new AgentTaskOptions{allowed=new List<string>{entry.id}}};var call=lib.PrepareAgentCall(state,new AgentAction{tool="create_clip",args=new Dictionary<string,object>{{"id",entry.id},{"title","Agent clip"},{"text","模块化仓库"}}},"","");lib.WriteAgentTool(state,call,CancellationToken.None,new Operations(lib,null));check(((WorkspaceState)lib.WorkspaceSnapshot()).clips.Count==1&&lib.OperationStatus(call.id)=="applied","registered clip tools produce source-scoped operations and durable receipts");lib.OperationUndo(call.id);check(((WorkspaceState)lib.WorkspaceSnapshot()).clips.Count==0,"an Agent clip is undoable through the same global operation pipeline");
  check(File.ReadAllText(source).Contains("模块化仓库"),"migration, clipping and undo preserve the original source file");
  var owned=lib.CreateDocument("版本测试","md","","before");var signature=lib.DocumentSource(owned.id).signature;lib.SaveDocument(owned.id,"after",signature,new Dictionary<string,object>());var saved=lib.OperationList().Last(o=>o.title=="保存文档"&&o.patches.Any(p=>p.id==owned.id));lib.OperationUndo(saved.id);check(File.ReadAllText(owned.path)=="before"&&lib.DocumentSource(owned.id).text=="before","global document undo restores both file bytes and editing state");
  signature=lib.DocumentSource(owned.id).signature;lib.SaveDocument(owned.id,"next",signature,new Dictionary<string,object>());saved=lib.OperationList().Last(o=>o.title=="保存文档"&&o.patches.Any(p=>p.id==owned.id));File.WriteAllText(owned.path,"external");check(Reject(()=>lib.OperationUndo(saved.id))&&File.ReadAllText(owned.path)=="external","document undo preserves content changed by another application");
  string jobsDir=Path.Combine(root,"jobs");Directory.CreateDirectory(jobsDir);var jobs=new Jobs(jobsDir,null);var context=new ModuleContext(lib,null,new ModulePolicy(lib),null,CancellationToken.None,null,new Operations(lib,null),jobs);var started=new TaskCompletionSource<bool>();var spec=new ActionSpec{Name="indexLibrary",Module="workspace",Requires=Need.NormalLibrary,Writes=true,Kind="write",Schema=CapabilitySchema.Obj(),Execute=async(c,a)=>{started.TrySetResult(true);await Task.Delay(5000,c.Jobs.CurrentToken);return true;}};
  var running=jobs.RunAction(context,spec,new Dictionary<string,object>());started.Task.GetAwaiter().GetResult();var job=jobs.Snapshot().Single();jobs.Control(context,job.id,"pause").GetAwaiter().GetResult();try{running.GetAwaiter().GetResult();}catch(OperationCanceledException){}var restored=new Jobs(jobsDir,null);check(restored.Snapshot().Single().state=="paused","managed background work records a durable pause without auto-running on restart");
  int calls=0;var next=new ModuleContext(lib,null,new ModulePolicy(lib),null,CancellationToken.None,null,new Operations(lib,null),restored);var resume=new ActionSpec{Name="indexLibrary",Module="workspace",Requires=Need.NormalLibrary,Writes=true,Kind="write",Schema=CapabilitySchema.Obj(),Execute=(c,a)=>{calls++;return Task.FromResult((object)true);}};next.Invoke=(name,args)=>restored.RunAction(next,resume,args);restored.Control(next,job.id,"resume").GetAwaiter().GetResult();check(calls==1&&restored.Snapshot().Single().state=="done","explicit resume reuses the managed job and runs exactly once");
  var linked=lib.CreateDocument("链接目标","md","","Target text");lib.Update(entry.id,new Dictionary<string,object>{{"notes","[["+linked.id+"]]"}});var graph=lib.BuildKnowledgeIndex();var relations=lib.RelatedLinks(linked.id);check(graph.links.Any(l=>l.source==entry.id&&l.target==linked.id)&&relations.Any(l=>l.source==entry.id&&l.target==linked.id),"graph and backlinks read the same durable relationship rows");lib.Update(entry.id,new Dictionary<string,object>{{"notes","Unlinked"}});check(!lib.RelatedLinks(linked.id).Any(l=>l.source==entry.id&&l.kind=="link"),"removing a note link refreshes the persisted backlink without leaving a stale edge");
  var recipe=new RecipeRecord{id=Guid.NewGuid().ToString("N"),name="Read to note",steps=new List<RecipeStep>{new RecipeStep{capability="documents.read",args=new Dictionary<string,object>{{"id",entry.id}}},new RecipeStep{capability="documents.createDocument",args=new Dictionary<string,object>{{"name","Recipe result"},{"format","md"},{"text","$previous.text"}}}}};var recipeOp=lib.ProposeResource("recipe",recipe.id,Library.Json.Serialize(recipe));lib.OperationApply(recipeOp.id);context.Invoke=(name,args)=>ModuleRegistry.Builtins.Dispatch(context,name,args);var plan=RecipePlans.Preview(context,recipe.id);check(plan.problems.Count==0&&plan.aiCalls==0,"recipe preflight validates every step and identifies a fully local workflow");
  context.Invoke("recipeRun",new Dictionary<string,object>{{"id",recipe.id},{"version",plan.version}}).GetAwaiter().GetResult();var output=lib.Db.items.Last(i=>i.name=="Recipe result");check(File.ReadAllText(output.path).Contains("模块化仓库")&&lib.OperationList().Any(o=>o.createdItemId==output.id&&o.source=="recipe:"+recipe.id),"recipe outputs retain readable source content and join global operation history");
  lib.Update(entry.id,new Dictionary<string,object>{{"notes","Changed since review"}});check(Reject(()=>context.Invoke("recipeRun",new Dictionary<string,object>{{"id",recipe.id},{"version",plan.version}}).GetAwaiter().GetResult())&&lib.Db.items.Count(i=>i.name=="Recipe result")==1,"a source change invalidates a reviewed plan before any additional output is written");
  lib.SetModuleEnabled("documents",false);check(RecipePlans.Preview(context,recipe.id).problems.Count>0,"recipe preflight blocks a disabled module before executing any steps");lib.SetModuleEnabled("documents",true);
  var importData=Path.Combine(root,"cancel-import");var partial=new Library(importData);using(var cancel=new CancellationTokenSource()){try{partial.Import(CancelAfterFirst(source,linked.path,cancel),null,cancel.Token);}catch(OperationCanceledException){}check(new Library(importData).Db.items.Count==1&&File.Exists(source)&&File.Exists(linked.path),"cancelling an import preserves committed entries across restart and never removes either original file");}
  string privateDir=Path.Combine(root,"private-index");using(var vault=VaultSession.Create(privateDir,"warehouse-index-test-password")){var secured=new Library(privateDir,vault);secured.Import(new[]{source},null);var secret=secured.Db.items.Single();secured.IndexItem(secret,"私密正文检索测试");check(new Library(privateDir,vault).FullTextSearch("正文检索").Contains(secret.id)&&Directory.GetFiles(privateDir,"*",SearchOption.AllDirectories).All(f=>!Encoding.UTF8.GetString(File.ReadAllBytes(f)).Contains("私密正文检索测试"))&&!File.Exists(Path.Combine(privateDir,"library.sqlite")),"private full-text indexing survives reopen inside the encrypted in-memory database without plaintext SQLite files");}
  var searchable=lib.CreateDocument("检索更新","md","","原先正文标记");lib.IndexItem(searchable,"原先正文标记");lib.SaveDocument(searchable.id,"新正文标记",lib.DocumentSource(searchable.id).signature,new Dictionary<string,object>());check(lib.FullTextSearch("新正文标记").Contains(searchable.id)&&!lib.FullTextSearch("原先正文标记").Contains(searchable.id),"saving a managed document updates search atomically and removes the stale body index");
  var subtitleItem=lib.Find(entry.id);subtitleItem.generatedSubtitles=new SubtitleTrack{cues=new List<Cue>{new Cue{start=0,end=1,text="字幕独有检索内容"}}};lib.Save();check(lib.FullTextSearch("字幕独有检索").Contains(subtitleItem.id),"generated subtitle text participates in unified full-text search");
  lib.CacheRecipeSummary("stable-source","Cached result");check(new Library(data).CachedRecipeSummary("stable-source")=="Cached result"&&lib.CachedRecipeSummary("changed-source")==null,"recipe summaries persist under an exact input fingerprint and do not cross changed sources");
  var firstBatch=lib.Find(entry.id);var secondBatch=lib.Find(linked.id);string oldFirst=firstBatch.notes,oldSecond=secondBatch.notes;firstBatch.notes="Batch edit one";secondBatch.notes="Batch edit two";lib.Save();var editBatch=lib.OperationList().Last(o=>o.state=="applied"&&o.patches.Count==2);lib.OperationUndo(editBatch.id);check(firstBatch.notes==oldFirst&&secondBatch.notes==oldSecond,"one compatibility batch save becomes one atomic global undo across all edited files");
  var badRecipe=new RecipeRecord{id=Guid.NewGuid().ToString("N"),name="Invalid referenced step",steps=new List<RecipeStep>{new RecipeStep{capability="documents.read",args=new Dictionary<string,object>{{"id",entry.id}}},new RecipeStep{capability="documents.createDocument",args=new Dictionary<string,object>{{"text","$previous.text"}}}}};var badRecipeOp=lib.ProposeResource("recipe",badRecipe.id,Library.Json.Serialize(badRecipe));lib.OperationApply(badRecipeOp.id);check(RecipePlans.Preview(context,badRecipe.id).problems.Count>0,"preflight rejects missing required fields even when a step contains a previous-result reference");
  check(RecipeText.Excerpt(new String('头',40000)+new String('尾',40000)).Length<=40000&&RecipeText.Excerpt(new String('头',40000)+new String('尾',40000)).EndsWith(new String('尾',100)),"long-source recipes bound their evidence while retaining the source ending");
  var agentSearch=Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(lib.AgentSearch(new Dictionary<string,object>{{"query","字幕独有检索"}},new List<string>{entry.id})));check(Library.Json.Serialize(agentSearch["ids"]).Contains(entry.id),"Agent search uses the same scoped full-text index as the library UI");
  string videoFile=Path.Combine(root,"tool-video.mp4");File.WriteAllBytes(videoFile,new byte[]{0,1,2,3});lib.Import(new[]{videoFile},null);var video=lib.Db.items.Single(i=>i.path==videoFile);var speechTool=AgentRules.Tools.Single(t=>t.Name=="generate_subtitles");var speechState=new AgentTaskState{id=Guid.NewGuid().ToString("N"),options=new AgentTaskOptions{allowed=new List<string>{video.id}}};var speechCall=lib.PrepareAgentCall(speechState,new AgentAction{tool="generate_subtitles",args=new Dictionary<string,object>{{"id",video.id}}},"","");
  int subtitleDispatches=0;string beforeSubtitles=lib.AgentSourceStamps(new[]{video.id})[video.id];context.Invoke=(name,args)=>{subtitleDispatches++;check(name=="generateSubtitles"&&Convert.ToString(args["id"])==video.id,"module-owned async Agent tools dispatch only their scoped native capability");var track=new SubtitleTrack{cues=new List<Cue>{new Cue{start=1,end=2,text="视频的已生成字幕证据"}}};lib.Find(video.id).generatedSubtitles=track;lib.Save();return Task.FromResult((object)track);};speechTool.ExecuteWithContext(context,speechState,speechCall,CancellationToken.None).GetAwaiter().GetResult();check(lib.OperationStatus(speechCall.id)=="applied"&&lib.BuildKnowledgeContext(new List<string>{video.id},"summarize","",6000).context.Contains("已生成字幕证据"),"an approved subtitle tool creates a durable receipt and its text becomes readable Agent evidence");speechTool.ExecuteWithContext(context,speechState,speechCall,CancellationToken.None).GetAwaiter().GetResult();check(subtitleDispatches==1&&beforeSubtitles!=lib.AgentSourceStamps(new[]{video.id})[video.id],"subtitle evidence invalidates read caches while a repeated committed call reuses its receipt");lib.OperationUndo(speechCall.id);check(lib.Find(video.id).generatedSubtitles==null,"generated subtitle changes share global conflict-safe undo without touching the video bytes");
  context.Invoke=(name,args)=>ModuleRegistry.Builtins.Dispatch(context,name,args);
  var inheritedStarted=new TaskCompletionSource<bool>();var inheritedSpec=new ActionSpec{Name="generateSubtitles",Module="speech",Requires=Need.Ai|Need.Network|Need.NormalLibrary,Writes=true,Kind="write",Schema=CapabilitySchema.Obj(),Execute=async(c,a)=>{inheritedStarted.TrySetResult(true);await Task.Delay(5000,c.Jobs.CurrentToken);return true;}};using(var parentCancel=new CancellationTokenSource()){var child=jobs.WithCancellation(()=>jobs.RunAction(context,inheritedSpec,new Dictionary<string,object>()),parentCancel.Token);inheritedStarted.Task.GetAwaiter().GetResult();parentCancel.Cancel();try{child.GetAwaiter().GetResult();}catch(OperationCanceledException){}check(jobs.Snapshot().Last(j=>j.detail=="generateSubtitles").state=="cancelled","cancelling a parent Agent token cancels a module job instead of leaving it running or marking it failed");}
  var orphan=lib.CreateDocument("可恢复来源","md","","Retain this source");var orphanSpace=new SpaceRecord{id=Guid.NewGuid().ToString("N"),name="Orphan space",members=new List<string>{orphan.id}};var orphanSpaceOp=lib.ProposeResource("space",orphanSpace.id,Library.Json.Serialize(orphanSpace));lib.OperationApply(orphanSpaceOp.id);var orphanClip=new ClipRecord{id=Guid.NewGuid().ToString("N"),title="Source note",text="Keep this thought",source=new SourceAnchor{itemId=orphan.id}};lib.OperationApply(lib.ProposeResource("clip",orphanClip.id,Library.Json.Serialize(orphanClip)).id);lib.Remove(orphan.id);orphanSpace.view="canvas";lib.OperationApply(lib.ProposeResource("space",orphanSpace.id,Library.Json.Serialize(orphanSpace)).id);orphanClip.text="The thought is still editable";lib.OperationApply(lib.ProposeResource("clip",orphanClip.id,Library.Json.Serialize(orphanClip)).id);check(((WorkspaceState)lib.WorkspaceSnapshot()).spaces.Any(s=>s.id==orphanSpace.id&&s.view=="canvas")&&((WorkspaceState)lib.WorkspaceSnapshot()).clips.Any(c=>c.id==orphanClip.id&&c.text==orphanClip.text)&&File.Exists(orphan.path),"unavailable sources do not block Space views or clip notes, and removing a reference preserves source bytes");
  lib.Settings(new Dictionary<string,object>{{"theme","dark"}});check(Reject(()=>lib.Settings(new Dictionary<string,object>{{"theme","light"},{"skin","invalid-skin"}}))&&Convert.ToString(lib.Db.settings["theme"])=="dark"&&Convert.ToString(new Library(data).Db.settings["theme"])=="dark","a late settings validation failure rolls back earlier fields in memory and on disk");
  string historyDir=Path.Combine(root,"long-history");Directory.CreateDirectory(historyDir);var historical=new Database{operations=Enumerable.Range(0,600).Select(n=>new Operation{id=Guid.NewGuid().ToString("N"),module="library",source="user",title="Historical record "+n,created=DateTime.UtcNow.AddMinutes(-600+n).ToString("o"),state="skipped"}).ToList()};File.WriteAllText(Path.Combine(historyDir,"library.json"),Library.Json.Serialize(historical));var historyLibrary=new Library(historyDir);check(historyLibrary.Db.operations.Count==512&&Library.Json.Deserialize<Database>(historyLibrary.Snapshot()).operations.Count==600&&historyLibrary.OperationList(500,100).Count==100,"history paging and compatibility export preserve all 600 records beyond the in-memory window");
  string scaleDir=Path.Combine(root,"large-search");Directory.CreateDirectory(scaleDir);var scaleData=new Database{items=Enumerable.Range(0,6001).Select(n=>new Entry{id=n.ToString("x32"),name="Scale document "+n,path=Path.Combine(scaleDir,"sources",n+".md"),kind="document",ext="MD",added=DateTime.UtcNow.ToString("o"),collection=n==6000?"last-only":"other",tags=new List<string>{"中文范围匹配标记"}}).ToList()};scaleData.settings["appMode"]="smart";scaleData.settings["smartModeNoticeSeen"]=true;File.WriteAllText(Path.Combine(scaleDir,"library.json"),Library.Json.Serialize(scaleData));var scaleLibrary=new Library(scaleDir);string lastId=scaleData.items.Last().id;
  check(scaleLibrary.FullTextSearch("范围匹配").Count==6001&&scaleLibrary.FullTextSearch("范围").Count==6001,"full-text and short Chinese queries retain every match beyond 5000 entries");
  var scaleQuery=new CollectionQuery{id=Guid.NewGuid().ToString("N"),name="Last matching item",query="范围匹配",kind="document",tag="中文范围匹配标记"};check(scaleLibrary.QueryCollection(scaleQuery).Count==6001,"smart collections do not truncate the full-text candidates before applying their criteria");
  check(Library.Json.Serialize(scaleLibrary.AgentSearch(new Dictionary<string,object>{{"query","范围匹配"}},new List<string>{lastId})).Contains(lastId),"Agent search finds an allowed source beyond the former global candidate limit without broadening scope");
